function presentXpAward(result){
 // Audio belongs to a real visible award, not to whether the gameplay HUD is mounted.
 // Motion synchronously cancels old SFX when scoring starts; schedule this new
 // durable chime after that cancellation, never in a timer or a replay backlog.
 // Recheck visibility/restore guards; sfx enforces preferences and trusted unlock.
 if(xpAudioAllowed())queueMicrotask(()=>{if(xpAudioAllowed())window.BOAudio?.sfx('xp',{amount:result.awardedXp})});
 presentLevelUp(result);if(result?.toLevel>result?.fromLevel&&playerLevel()>=5){pendingEmeraldLevelReaction=true;emeraldActions?.queue(['Level up for you, awesome!'])}
}
function queueLevelUp(result,committed=false){
 if(result&&typeof result==='object'&&Number.isFinite(result.awardedXp)&&result.awardedXp>0&&!result.duplicate&&result.ok!==false){
  if(xpAwardsSeen.has(result))return;xpAwardsSeen.add(result);
  if(committed)presentXpAward(result);else pendingXpAwards.push({result,progression:profile.progression});
 }else presentLevelUp(result);
}
