function runPurchaseMeta(kind,index){return kind==='item-use'?{action:'buy-use',index,itemType:run.shop.items[index]?.type}:kind==='item'?{action:'buy',index,itemType:run.shop.items[index]?.type}:kind==='voucher'?{action:'voucher'}:kind==='pack'?{action:'pack',index}:kind==='boss'?{action:'reroll-boss'}:{action:'reroll'}}
