const jokerMultBanks=new Set(['ride_the_bus','green_joker','double_green_joker','red_card','flash_card','popcorn','spare_trousers','ceremonial_dagger','venipede_joker']);
const jokerChipBanks=new Set(['runner','ice_cream','square_joker','castle','wee_joker','krillistic','mantis']);
const jokerXMultBanks=new Set(['constellation','madness','vampire','hologram','lucky_cat','ramen','campfire','glass_joker','hit_the_road','canio','yorick','obelisk']);
function jokerCurrentLines(j,context){
  const owned=context==='owned',active=E.isJokerActive?E.isJokerActive(j):!(j.disabled||j.permanentDisabled),number=n=>fmt(Number(n.toFixed(8))),prefix=owned?(active?'Currently':'Stored'):Number.isFinite(j.counter)?'Offered':'Starts at',suffix=owned&&!active?' · inactive':'',lines=[];
  if(j.id==='blueprint'||j.id==='brainstorm'){
    if(!owned)return ['Copy target depends on your Joker order after acquisition.'];
    if(!E.copyInfo)return [];
    const info=E.copyInfo(run,j.uid),target=run.jokers.find(x=>x.uid===info.terminalTargetUid),last=run.jokers.find(x=>x.uid===info.path.at(-1));
    if(info.status==='compatible'&&target)return ['Currently copying '+info.terminalName,...jokerCurrentLines(target,'owned').map(s=>s.replace(/^Currently /,'Copied effect: '))];
    if(info.status==='incompatible')return ['Cannot copy '+(info.terminalName||'this target')+' · incompatible ability'];
    if(info.status==='disabled')return ['Copy inactive: '+(last?jokerDef(last).name:'target')+' is disabled or expired'];
    return [info.status==='cycle'?'Copy inactive: copy loop':'Copy inactive: no target at the end of the copy chain'];
  }
  if(j.id==='oops_all_sixes'){
    if(!owned)return ['Each active copy: ×2 listed probabilities'];
    const info=E.probabilityInfo?.(run);return info?[...(info.playerLuckMultiplier>1||info.potionLuckMultiplier>1?['Each active copy: ×2 listed probabilities']:[]),'Currently ×'+probabilityNumber(info.multiplier)+' listed probabilities'+(info.playerLuckMultiplier>1||info.potionLuckMultiplier>1?' total':'')+' · '+info.activeOops+' active Oops '+(info.activeOops===1?'copy':'copies')+(info.playerLuckMultiplier>1?' · +25% player luck':'')+(info.potionLuckMultiplier>1?' · ×2 Luck Potion':'')]:[];
  }
  if(j.id==='drivers_license'&&owned)lines.push('Currently '+(run?.cards||[]).filter(c=>!!c.enhancement).length+'/16 enhanced cards'+suffix);
  const bank=jokerMultBanks.has(j.id)?'Mult':jokerChipBanks.has(j.id)?'Chips':jokerXMultBanks.has(j.id)?'×':null;
  if(bank){
    const start=jokerXMultBanks.has(j.id)?(j.id==='ramen'?2:1):j.id==='ice_cream'?100:j.id==='popcorn'?20:0,value=Number.isFinite(j.counter)?j.counter:owned?null:start;
    if(value!==null)lines.push(prefix+' '+(bank==='×'?'×'+number(value)+' Mult':'+'+number(value)+' '+bank)+suffix);
  }
  // Non-scoring clocks retain their real units instead of becoming fake Mult.
  if(Number.isFinite(j.counter))switch(j.id){
    case 'turtle_bean':lines.push(prefix+' +'+number(j.counter)+' hand size'+suffix);break;
    case 'seltzer':lines.push(number(j.counter)+' played '+(j.counter===1?'hand':'hands')+' of retriggers remaining'+suffix);break;
    case 'rocket':lines.push(prefix+' $'+number(j.counter)+' per round; Boss wins add $2 before payout'+suffix);break;
    case 'loyalty_card':{const left=6-j.counter%6;lines.push('Next ×4 Mult in '+number(left)+' played '+(left===1?'hand':'hands')+suffix);break;}
    case 'invisible_joker':lines.push(j.counter>=2?'Ready to copy on sale if another Joker and space are available'+suffix:number(j.counter)+' / 2 winning rounds before sale can copy a Joker'+suffix);break;
  }
  if(j.id==='yorick'&&Number.isFinite(j.discarded))lines.push(number(j.discarded)+' / 23 cards discarded toward next multiplier increase');
  const suitNames={S:'Spades',H:'Hearts',D:'Diamonds',C:'Clubs'},whichSuit=suitNames[j.targetSuit],rank=Number.isInteger(j.targetRank)&&j.targetRank>=2&&j.targetRank<=14?(ranks[j.targetRank]||j.targetRank):null;
  if(j.id==='the_idol'&&rank&&whichSuit)lines.push('Current target: '+rank+' of '+whichSuit+' ('+suits[j.targetSuit]+')');
  else if(['castle','ancient_joker'].includes(j.id)&&whichSuit)lines.push('Current target: '+whichSuit+' ('+suits[j.targetSuit]+')');
  else if(j.id==='mail_in_rebate'&&rank)lines.push('Current target: '+rank);
  else if(j.id==='to_do_list'&&handNames[j.targetHand])lines.push('Current target: '+handNames[j.targetHand]);
  // Only these simple, owned live formulas are projected. Shelf/catalog objects
  // must not borrow current owned totals or pretend to occupy a future slot.
  if(owned&&active)switch(j.id){
    case 'big_spender':lines.push('Currently +'+number(Math.floor(Math.max(0,-run.money)/5))+' Mult');break;
    case 'joker_stencil':lines.push('Currently ×'+number(Math.max(1,E.summary(run).jokerSlots-run.jokers.length+run.jokers.filter(x=>x.id==='joker_stencil'&&(E.isJokerActive?E.isJokerActive(x):!x.disabled)).length))+' Mult');break;
    case 'egg':if(E.sellValue)lines.push('Current sell value: $'+number(E.sellValue(j)));break;
  }
  return lines;
}
