function ensureCloudClient(){if(!CS)throw new Error('Cloud saves are unavailable. Keep cloud-save.js with the game.');if(!cloudClient)cloudClient=CS.createClient({recovery:cloudCallback,onChange:paintCloud});return cloudClient;}
function closeCloud(){if(!$('#cloud-account'))return;const recovery=cloudClient?.status().recovery?.active;cloudSerial++;cloudBusy=false;cloudPending=null;clearCloudPasswords();cloudClient?.cancel();cloudRecoveryView='';if(recovery)cloudMessage=cloudClient.status().message||'Password recovery cancelled. Request a new reset link to try again. Local game progress was not changed.';}
async function cloudTask(fn,{interrupt=false}={}){if(cloudRestoring)return {ok:false,reason:'Reload to finish save replacement.'};if(cloudBusy&&!interrupt)return {ok:false,reason:'Wait for the current account action.'};const serial=++cloudSerial;cloudBusy=true;cloudMessage='';if(!interrupt)cloudPending=null;$('#cloud-confirm')?.replaceChildren();paintCloud();try{const result=await fn();if(serial!==cloudSerial)return {ok:false,cancelled:true};paintCloud();return result;}catch(error){if(serial!==cloudSerial||error.code==='cancelled')return {ok:false,cancelled:true};cloudMessage=error.message||'Cloud action failed. Your local progress is safe.';paintCloud();return {ok:false,reason:cloudMessage};}finally{if(serial===cloudSerial){cloudBusy=false;paintCloud()}}}
function cloudOpen({resume=true}={}){
 if(cloudRestoring)return;if(!CS){toast('Cloud saves are unavailable in this build.');return;}
 const client=ensureCloudClient(),view=cloudRecoveryView;
 if(client.status().recovery.active&&$('#cloud-account')){paintCloud();return;}
 cloudPending=null;
 const request=`<section id="cloud-reset-request"><h3>Request a reset link</h3><p class="cloud-note">If you reloaded or closed a recovery tab, request a new reset link. Recovery links are never saved by the game. Nothing is emailed until you press Send reset link.</p><div class="cloud-credentials"><label for="cloud-reset-email">Email<input id="cloud-reset-email" type="email" autocomplete="email" autocapitalize="none" spellcheck="false" inputmode="email" maxlength="320" data-private="true"></label></div><div class="cloud-actions">${btn('Send reset link','cloud-request-reset','primary')}</div></section>`;
 const recovery=`<section id="cloud-recovery" aria-label="Password recovery"><h3>Recover your password</h3><p class="cloud-note">This does not log you in, transfer progress, or change any existing cloud account session. Verify the link's account first, then explicitly confirm it. Reloading or closing this tab discards the link.</p><div id="cloud-recovery-verification">${btn('Verify recovery account','cloud-recovery-verify','primary')}</div><section id="cloud-recovery-passwords" hidden><p>Verified account: <strong id="cloud-recovery-email"></strong></p><label class="cloud-recovery-consent" for="cloud-recovery-confirm-account"><input id="cloud-recovery-confirm-account" type="checkbox" autocomplete="off">I confirm this is the account whose password I want to change.</label><div class="cloud-credentials"><label for="cloud-new-password">New password<input id="cloud-new-password" type="password" autocomplete="new-password" autocapitalize="none" spellcheck="false" minlength="6" maxlength="1024" data-private="true"></label><label for="cloud-confirm-password">Repeat new password<input id="cloud-confirm-password" type="password" autocomplete="new-password" autocapitalize="none" spellcheck="false" minlength="6" maxlength="1024" data-private="true"></label></div><p class="cloud-note">Use at least 6 characters. Both passwords must match. Password fields clear as soon as you submit.</p><div class="cloud-actions">${btn('Set new password','cloud-update-password','primary',true)}</div></section></section>`;
 const normal=`<div class="cloud-credentials"><label for="cloud-email">Email<input id="cloud-email" type="email" autocomplete="email" autocapitalize="none" spellcheck="false" inputmode="email" maxlength="320" data-private="true"></label><label for="cloud-password">Password<input id="cloud-password" type="password" autocomplete="current-password" autocapitalize="none" spellcheck="false" minlength="6" maxlength="1024" data-private="true"></label></div><div class="cloud-actions">${btn('Sign up','cloud-signup','ghost')}${btn('Log in','cloud-login','primary')}${btn('Forgot password','cloud-forgot','ghost')}</div><p class="cloud-note">Use an email address you can confirm. After the confirmation email, return here and log in with your password. Passwords are never saved by the game or included in saves.</p>`;
 modal(view?'Password recovery':'Account & Cloud',`<section id="cloud-account" class="cloud-account" aria-label="Account and manual cloud saves"><p class="cloud-kicker">OPTIONAL ACCOUNT · MANUAL SAVES</p><p id="cloud-identity"></p><p id="cloud-status" role="status" aria-live="polite"></p>${view==='recovery'?recovery:''}${view?request:normal}${view?'<div id="cloud-recovery-complete" class="cloud-actions" hidden>'+btn('Back to log in','cloud-recovery-login','primary')+'</div>':''}<div class="cloud-actions">${view?btn('Cancel recovery','cloud-recovery-cancel','ghost'):''}${btn('Log out','cloud-logout','ghost')}</div><hr class="settings-divider"><div class="cloud-actions">${btn('Save to Cloud','cloud-upload','primary')}${btn('Load from Cloud','cloud-download','ghost')}${btn('Restore local backup','cloud-backup','ghost')}</div><div id="cloud-confirm" aria-live="polite"></div><p class="cloud-note">Manual cloud saves include your settings and any selected background/card-back images. Images are not uploaded by choosing them or by logging in.</p><p class="cloud-note">Save to Cloud replaces this account’s cloud progress only after confirmation if a save exists. Load replaces only the selected local slot’s progress, run and settings after confirmation, with that slot’s durable local backup first. The other two slots are not changed. Logging in, recovering a password or switching accounts never transfers progress.</p><p class="cloud-note">Finish pending surveys and bank their rewards first. Completed receipts and disqualification history are preserved; active survey quests are not transferred. Close other game tabs before loading. This optional account uses Supabase and needs Internet; local play does not require an account.</p></section>`);
 cloudRecoveryView=view;paintCloud();if(!view&&resume)void cloudTask(()=>client.resume());
}
function cloudForgot(){const email=$('#cloud-email')?.value||'';closeCloud();cloudRecoveryView='request';cloudMessage='Request a fresh password reset link. Reloading or closing a recovery tab discards its private link.';cloudOpen({resume:false});if($('#cloud-reset-email'))$('#cloud-reset-email').value=email;}
function cloudRequestReset(email=$('#cloud-reset-email')?.value||''){clearCloudPasswords();return cloudTask(()=>ensureCloudClient().requestPasswordReset(email));}
function cloudVerifyRecovery(){clearCloudPasswords();return cloudTask(()=>ensureCloudClient().verifyRecovery());}
function cloudUpdatePassword(){const password=$('#cloud-new-password')?.value||'',matching=$('#cloud-confirm-password')?.value||'',state=cloudClient?.status().recovery,consent=$('#cloud-recovery-confirm-account')?.checked===true;clearCloudPasswords();return cloudTask(()=>ensureCloudClient().updatePassword(password,matching,{confirmed:consent,expectedUserId:state?.user?.id}));}
function cloudBackToLogin(){const message=cloudMessage||cloudClient?.status().message||'Password updated. Log in normally with your new password.';closeCloud();cloudRecoveryView='';cloudMessage=message;cloudOpen({resume:false});return {ok:true};}
function cloudCancelRecovery(){closeCloud();cloudMessage=cloudClient?.status().message||'Recovery cancelled. Request a new reset link to try again. Local game progress was not changed.';cloudRecoveryView='';cloudOpen({resume:false});return {ok:true};}
function cloudCredentials(kind,email,password){const client=ensureCloudClient();if(email===undefined)email=$('#cloud-email')?.value||'';if(password===undefined)password=$('#cloud-password')?.value||'';if($('#cloud-password'))$('#cloud-password').value='';return cloudTask(async()=>{const result=await client[kind](email,password);cloudMessage=kind==='signup'?'Check your email to confirm the account, then log in. Email delivery and limits depend on the email service.':'Logged in. No game progress was transferred.';return result;});}
function cloudIdle(){if(cloudClient?.status().recovery.active)throw new Error('Finish or cancel password recovery before any cloud save transfer or local backup restore.');assertEconomyWritable();if(animating||surveyViewActive()||surveys?.status().screenPhase||surveys?.status().pending||dailyStreak?.status().pending||dailyTasks?.status().pending||interest?.status().pending)throw new Error('Finish the current action or survey, then try cloud saves again.');if(!writerGuard)throw new Error('Save ownership is unavailable. Reload in a current browser.');}
function cloudCapture(){cloudIdle();dailyTasks?.refresh();dailyStreak?.refresh();if(!persist()||localStorage.getItem(PROFILE)!==JSON.stringify(profile)||localStorage.getItem(SAVE)!==(run?JSON.stringify(run):null)||localStorage.getItem(SETTINGS)!==JSON.stringify(prefs))throw new Error('The complete local save could not be flushed. Nothing was uploaded or replaced.');return CS.capture(localStorage);}
function showCloudConfirm(kind,result){cloudPending={kind,...result,reset:localStorage.getItem(CS.RESET_KEY)};const root=$('#cloud-confirm');if(!root)return;root.innerHTML='<div class="cloud-confirm-box"><h3></h3><p></p><div class="cloud-actions">'+btn(kind==='upload'?'Replace cloud save':'Replace selected slot','cloud-confirm','danger')+btn('Cancel','cloud-cancel','ghost')+'</div></div>';root.querySelector('h3').textContent=kind==='upload'?'Replace this account’s cloud save?':'Replace the selected slot?';root.querySelector('p').textContent=kind==='upload'?'Your existing cloud save will be replaced by the current local progress. Other devices do not update automatically.':'This replaces only the selected slot’s player progress, run, Medals, receipts, potions and settings. Its local backup is saved first, then the game reloads. The other two slots are not changed.';}
async function cloudUpload(consent=null){const client=ensureCloudClient();return cloudTask(async()=>{const serial=cloudSerial,revision=client.status().revision,guard=()=>{if(serial!==cloudSerial||revision!==client.status().revision)throw Object.assign(new Error('Cloud action cancelled.'),{code:'cancelled'});if(consent&&(consent.revision!==client.status().revision||consent.userId!==client.status().user?.id||consent.reset!==localStorage.getItem(CS.RESET_KEY)))throw new Error('Your account or progress changed. Start Save to Cloud again.');};guard();const snapshot=await cloudLocks(()=>{guard();return cloudCapture();});guard();const result=await client.upload(snapshot,{overwriteConfirmed:!!consent,expectedUserId:consent?.userId,expectedUpdatedAt:consent?.updatedAt});if(result.needsConfirmation){showCloudConfirm('upload',result);cloudMessage='A cloud save already exists. Confirm before overwriting it.';}else cloudMessage='Saved to Cloud. Other devices must choose Load from Cloud manually.';return result;});}
async function cloudDownload(){const client=ensureCloudClient();return cloudTask(async()=>{cloudIdle();const result=await client.download();if(!result){cloudMessage='This account has no cloud save yet. Choose Save to Cloud to create one.';return {ok:true,empty:true};}showCloudConfirm('download',result);cloudMessage='Cloud save checked. Confirm below to replace local progress.';return {needsConfirmation:true};});}
function quiesceCloudRestore(){batteryController?.suspend();batteryController?.destroy();cloudRestoring=true;document.querySelector('#emerald-dialog-slot')?.remove();clearInterval(passiveTimer);clearInterval(marketTimer);clearInterval(potionTimer);clearTimeout(longTimer);clearTimeout(toastTimer);cancelMotion();pendingRunReplacement=null;pendingLevelCelebration=null;interest?.destroy();passiveMoneyController?.destroy();surveys?.destroy();dailyStreak?.reset();dailyStreak?.destroy();dailyTasks?.destroy();market?.reset();potions?.destroy?.();document.querySelector('#level-celebration')?.remove();window.BOAudio?.cancelEffects();}
async function cloudReplace(snapshot,guard,restoreGuard=()=>{}){CS.validateSnapshot(snapshot);try{return await cloudLocks(()=>{guard();cloudIdle();cloudCapture();restoreGuard();quiesceCloudRestore();const result=CS.restore(localStorage,snapshot,{assertOwner:()=>{writerGuard.assert();restoreGuard()},currentUrl:location.href});cloudMessage='Complete save restored. Reloading safely…';paintCloud();return result;});}finally{if(cloudRestoring)cloudReload();}}
function cloudBackup(){return cloudTask(async()=>{cloudIdle();const snapshot=CS.readBackup(localStorage);showCloudConfirm('backup',{snapshot});cloudMessage='Confirm below to restore the pre-restore local backup. The current local save will become the next backup.';return {needsConfirmation:true};});}
function cloudConfirm(){const consent=cloudPending;if(!consent)return Promise.resolve({ok:false});cloudPending=null;if(consent.kind==='upload')return cloudUpload(consent);return cloudTask(async()=>{const serial=cloudSerial,guard=()=>{const state=cloudClient?.status();if(serial!==cloudSerial)throw Object.assign(new Error('Save replacement cancelled.'),{code:'cancelled'});if(consent.reset!==localStorage.getItem(CS.RESET_KEY))throw new Error('Local progress changed. Request the save again.');if(consent.kind==='download'&&(consent.revision!==state?.revision||consent.userId!==state?.user?.id))throw new Error('The account changed. Load the cloud save again.');};guard();return cloudReplace(consent.snapshot,guard);});}
function cloudLogout(){clearCloudPasswords();return cloudTask(async()=>{cloudPending=null;await ensureCloudClient().logout();cloudMessage=cloudClient.status().message||'Logged out. Local game progress was not changed.';return {ok:true};},{interrupt:true});}
// Never turn an unreadable settings bank (which may contain personal photos) into
// empty defaults. Reuse the existing fail-closed Retry screen before controllers start.
function readBootPreferences(){try{const raw=localStorage.getItem(SETTINGS);if(raw===null)return {ok:true,value:null};const value=JSON.parse(raw);if(!value||typeof value!=='object'||Array.isArray(value))throw new Error('Invalid settings bank.');if(Object.prototype.hasOwnProperty.call(value,'username')&&PI?.validateUsername(value.username)!==true)throw new Error('Invalid local username.');if(Object.prototype.hasOwnProperty.call(value,'emeraldTips')&&!EC.validTips(value.emeraldTips))throw new Error('Invalid Emerald tip preferences.');return {ok:true,value}}catch(_){return blockSaveRead()}}
function customImageControlsDisabled(){return !slotChosen||saveReadBlocked||!!customImageBusy||writerGuard?.status().writable===false||cloudRestoring||slotBusy||cloudBusy||!!cloudPending||!!cloudClient?.status().pending}
function refreshCustomImageControls(){const target=$('#custom-images-settings');if(!target)return;const unlocked=String(Number.isSafeInteger(playerLevel())&&playerLevel()>=30);if(target.dataset.unlocked!==unlocked)paintCustomImageSettings();else target.disabled=customImageControlsDisabled()}
// Custom photos live only in this slot's existing settings. No media/network service is used.
function customImagesSettingsHTML(){if(!CI)return '<p class="build-note">Custom images are unavailable. Keep custom-images.js with the game.</p>';const disabled=customImageControlsDisabled();return `<fieldset id="custom-images-settings" data-unlocked="${Number.isSafeInteger(playerLevel())&&playerLevel()>=30}" style="border:0;padding:0;margin:24px 0;min-width:0" ${disabled?'disabled':''}>${CI.settingsHTML({level:playerLevel(),value:prefs.customImages,busy:customImageBusy})}<p id="custom-image-feedback" class="build-note" role="status" aria-live="polite">${esc(customImageFeedback||((writerGuard?.status().writable===false)?'This table is view-only. Close the other game tab before changing images.':''))}</p></fieldset>`}
function paintCustomImageSettings(){const target=$('#custom-images-settings');if(target)target.outerHTML=customImagesSettingsHTML()}
function assertCustomImageAccess(){if(!CI)throw new Error('Custom images are unavailable in this build.');if(!slotChosen||slotBusy||cloudRestoring||cloudBusy||cloudPending||cloudClient?.status().pending||surveyViewActive())throw new Error('Finish the current save or cloud action before changing images.');assertEconomyWritable();if(!Number.isSafeInteger(playerLevel())||playerLevel()<30)throw new Error('Custom images unlock at actual Player Level 30.')}
async function changeCustomImage(kind,file,remove=false){
 if(customImageBusy){toast('Please wait for the current image to finish.');return false;}
 let committed=false;
 try{
  if(!['background','cardBack','faceCard'].includes(kind))throw new Error('Choose a background, card-back or face-card image.');assertCustomImageAccess();
  const meta=slotStore.read(),context={profile,active:meta.active,generation:meta.slots[meta.active-1].generation,revision:meta.revision,cloudSerial};
  customImageBusy=kind;customImageFeedback='';paintCustomImageSettings();
  const image=remove?null:await CI.prepareFile(file,kind);
  // Reading/decoding can outlive a closed Settings sheet. Recheck the exact writer,
  // profile, slot generation and cloud epoch before touching any persisted bytes.
  assertCustomImageAccess();const current=slotStore.read();
  if(profile!==context.profile||current.active!==context.active||current.slots[current.active-1].generation!==context.generation||current.revision!==context.revision||cloudSerial!==context.cloudSerial)throw new Error('The selected save changed while the image was processing. Choose the image again.');
  const images=CI.validate(prefs.customImages)?{...prefs.customImages}:CI.defaults();images[kind]=image;if(!CI.validate(images))throw new Error('The processed image could not be validated.');
  const next={...prefs,customImages:images};if(images.background===null&&images.cardBack===null&&images.faceCard==null)delete next.customImages;
  const raw=JSON.stringify(next);
  if(!store(SETTINGS,next)||localStorage.getItem(SETTINGS)!==raw)throw new Error('The browser could not confirm saving this image. Your game progress was not replaced. Free storage and retry.');
  prefs=next;CI.apply(prefs.customImages,playerLevel());committed=true;
  customImageFeedback=(kind==='background'?'Background':kind==='faceCard'?'Face-card':'Card-back')+' '+(remove?'removed':'saved')+' in Slot '+context.active+'.';
 }catch(error){customImageFeedback=error.message||'The image could not be saved. Try again.';}
 finally{customImageBusy=false;if($('#custom-images-settings'))paintCustomImageSettings();else if(customImageFeedback)toast(customImageFeedback);}
 return committed;
}
// Language is an explicit, synchronous SETTINGS-only transaction through the existing store.
// Never call persist/render here: other Settings drafts, focused controls and PM-owned nodes survive.
function languageSettingsHTML(){if(!I18NModule||!i18n)return '<p class="build-note">Language preferences are unavailable. Keep all game files together.</p>';const id=i18n.getLocale();return `<section id="language-settings" aria-labelledby="language-settings-title"><h3 id="language-settings-title" data-i18n="language.title">Preferred language</h3><label for="preferred-language" data-i18n="language.label">Language</label><select id="preferred-language" aria-describedby="language-settings-note language-settings-feedback">${I18NModule.LANGUAGES.map(item=>`<option value="${item.id}" lang="${item.id}" translate="no" data-i18n-skip${item.id===id?' selected':''}>${esc(item.label)}</option>`).join('')}</select><p id="language-settings-note" class="build-note" data-i18n="language.note">Changing language saves only this preference in the selected slot. Your game, numbers and other settings stay unchanged.</p><p id="language-settings-feedback" role="status" aria-live="polite">${I18NModule.validLanguage(prefs.preferredLanguage)&&!i18n.availableLanguage(prefs.preferredLanguage)?esc(i18n.t('language.missing')):''}</p></section>`}
function bindLanguageSettings(){const root=$('#language-settings'),select=$('#preferred-language');languageContext=null;if(!root||!select)return;try{languageContext={root,select,profile,run,slot:slotStore.read().active,owner:writerGuard,stamp:runSlotStamp(),cloudSerial,auth:localStorage.getItem(CS.SESSION_KEY),reset:localStorage.getItem(SU.RESET_KEY),profileRaw:localStorage.getItem(PROFILE),runRaw:localStorage.getItem(SAVE)};}catch(error){const message=$('#language-settings-feedback');if(message)message.textContent=error.message;}}
function assertLanguageContext(context,attempt=null){
 if(!I18NModule||!i18n)throw new Error('Language preferences are unavailable. Keep all game files together.');
 if(!context||languageContext!==context||context.root!==$('#language-settings')||context.select!==$('#preferred-language')||!context.root.isConnected||$('#overlay').hidden)throw new Error('Open Settings before changing language.');
 if(document.hidden||!storageOK||passivePolling||textAppearanceBusy()||interest?.status().pending)throw new Error('Finish the current save, image, cloud, survey or Moving Mode action before changing language.');
 if(!conductAllowed())throw new Error('Playing is paused by the local conduct restriction.');slotIdle();assertEconomyWritable();if(!writerGuard)throw new Error('Save ownership is unavailable. Reload safely.');writerGuard.assert();
 if(interest?.status().blocked||passiveMoneyController?.status().uncertain||dailyTasks?.status().blocked||dailyTasks?.status().pendingCount||dailyStreak?.status().blocked)throw new Error('Saving needs attention. Bank pending rewards and reload safely before changing language.');
 if(profile!==context.profile||run!==context.run||writerGuard!==context.owner||runSlotStamp()!==context.stamp||cloudSerial!==context.cloudSerial||localStorage.getItem(CS.SESSION_KEY)!==context.auth||localStorage.getItem(SU.RESET_KEY)!==context.reset)throw new Error('The selected slot, owner or settings editor changed. Reopen Settings before changing language.');
 if(!attempt)return;
 if(JSON.stringify(profile)!==attempt.profileModelRaw||(run?JSON.stringify(run):null)!==attempt.runModelRaw){saveReadBlocked=true;storageOK=false;throw new Error('Progress changed during the language action. Saving is paused; reload safely before retrying.');}
 let profileRaw,runRaw;try{profileRaw=localStorage.getItem(PROFILE);runRaw=localStorage.getItem(SAVE)}catch(error){saveReadBlocked=true;storageOK=false;throw new Error('Canonical progress cannot be read safely. Saving is paused; reload before changing language.');}
 if(profileRaw!==attempt.profileRaw||runRaw!==attempt.runRaw){saveReadBlocked=true;storageOK=false;throw new Error('Stored progress changed during the language action. Saving is paused; reload before changing language.');}
}
function captureLanguageAttempt(context){
 assertLanguageContext(context);const profileModelRaw=JSON.stringify(profile),runModelRaw=run?JSON.stringify(run):null,profileRaw=localStorage.getItem(PROFILE),runRaw=localStorage.getItem(SAVE);
 if(profileRaw!==(lastProfileWriteRaw===null?context.profileRaw:lastProfileWriteRaw)||runRaw!==(lastRunWriteRaw===null?context.runRaw:lastRunWriteRaw)||profileModelRaw!==profileRaw||runModelRaw!==runRaw){saveReadBlocked=true;storageOK=false;throw new Error('Stored progress and this tab do not match confirmed saves. Saving is paused; reload safely before changing language.');}
 const attempt={profileRaw,runRaw,profileModelRaw,runModelRaw};assertLanguageContext(context,attempt);return attempt;
}
function changePreferredLanguage(select){
 const context=languageContext,previous=i18n?.getLocale()||'en-US';
 if(!I18NModule||!context||select!==context.select)return;
 const expectedSettingsRaw=JSON.stringify(prefs);let writtenSettingsRaw=null,attempt=null;
 const pause=()=>{saveReadBlocked=true;storageOK=false;};
 const read=()=>{let raw;try{raw=localStorage.getItem(SETTINGS)}catch(error){pause();throw error;}if(raw!==(writtenSettingsRaw===null?expectedSettingsRaw:writtenSettingsRaw)){pause();throw new Error('Stored settings differ from this tab. No language was applied. Saving is paused; reload safely before retrying.');}return raw;};
 const result=I18NModule.savePreference({available:id=>i18n.availableLanguage(id),read,assert:()=>{if(!attempt)attempt=captureLanguageAttempt(context);else assertLanguageContext(context,attempt);},context:()=>languageContext,write:next=>{writtenSettingsRaw=JSON.stringify(next);return store(SETTINGS,next);},apply:id=>{prefs={...prefs,preferredLanguage:id};i18n.setLocale(id);},pause},select.value,context);
 if(!result.ok)select.value=previous;const message=$('#language-settings-feedback');if(!message||!context.root.isConnected){if(!result.ok)toast((result.uncertain?i18n.t('language.uncertain'):i18n.t('language.unsaved'))+' '+result.message);return;}
 message.removeAttribute('data-i18n');message.removeAttribute('data-i18n-params');
 if(result.ok){message.setAttribute('data-i18n','language.saved');message.setAttribute('data-i18n-params',JSON.stringify({slot:context.slot}));message.textContent=i18n.t('language.saved',{slot:context.slot});}
 else{const prefix=result.uncertain?i18n.t('language.uncertain'):i18n.t('language.unsaved'),key=i18n.keyFor(result.message);message.textContent=key?i18n.t(key):prefix+' '+result.message;}
 i18n.apply(context.root);
}
// Text appearance is a synchronous, SETTINGS-only transaction. Draft controls never change prefs.
// File transfers use the cloud snapshot allowlist and the SAME durable restore,
// never a second Storage writer. A preview is only parsed, validated memory.
function invalidateProgressTransfer(){progressTransferSerial++;progressTransferContext=null}
function progressTransferSettingsHTML(){return `<section id="progress-transfer-settings" aria-labelledby="progress-transfer-title"><h3 id="progress-transfer-title">Move progress between devices</h3><div class="sheet-actions">${btn('Export Progress','export','primary')}${btn('Import Progress','import-progress','ghost')}</div><p class="build-note">Copies only your selected slot, including its run, player level, settings and custom photos. Photos are included in the JSON file: share it only with someone you trust. No account or internet is needed. Import replaces this slot, not merges; your other slots and cloud account stay unchanged.</p></section>`}
function assertProgressTransferReady(){
 if(!CS||!SS||!PG||!ER||!FZ)throw new Error('Progress transfer is unavailable. Keep all game files together.');
 if(document.hidden||!storageOK||passivePolling||textAppearanceBusy()||progressTransferContext?.phase==='committing')throw new Error('Finish the current save, image, Moving Mode, cloud or survey action first. If saving is uncertain, reload safely.');
 if(!conductAllowed())throw new Error('Playing is paused by the local conduct restriction.');slotIdle();assertEconomyWritable();if(!writerGuard)throw new Error('Save ownership is unavailable. Reload safely.');writerGuard.assert();
 if(interest?.status().blocked||passiveMoneyController?.status().uncertain||dailyTasks?.status().blocked||dailyTasks?.status().pendingCount||dailyStreak?.status().blocked)throw new Error('Saving needs attention. Bank pending rewards and reload safely before transferring progress.');
 if(cloudCallback.kind==='recovery'&&cloudCallback.handled||localStorage.getItem(CS.JOURNAL_KEY)!==null||localStorage.getItem(SS.JOURNAL_KEY)!==null)throw new Error('Finish save or account recovery before transferring progress.');
 SS.assertNoPendingSurvey(SS.snapshot(localStorage));
}
function progressTransferWitness(){const meta=slotStore.read();return {slot:meta.active,stamp:runSlotStamp(),profile,run,owner:writerGuard,cloudSerial,auth:localStorage.getItem(CS.SESSION_KEY),reset:localStorage.getItem(SU.RESET_KEY),raw:Object.fromEntries(CS.KEYS.map(key=>[key,localStorage.getItem(key)]))}}
function assertProgressTransferContext(context,flushed=false){
 if(!context||progressTransferContext!==context||context.serial!==progressTransferSerial||!context.root.isConnected||$('#overlay').hidden||$('#progress-transfer')!==context.root)throw new Error('This import was cancelled. Open Import Progress again.');
 if(!conductAllowed()||saveReadBlocked||!storageOK||document.hidden||writerGuard!==context.owner||profile!==context.profile||run!==context.run||cloudSerial!==context.cloudSerial||localStorage.getItem(CS.SESSION_KEY)!==context.auth||runSlotStamp()!==context.stamp)throw new Error('The selected slot, owner or save context changed. Open Import Progress again.');
 writerGuard.assert();
 // Once restore starts these exact keys/reset intentionally change. The existing
 // transaction rechecks the remaining slot/owner/modal/conduct fences at both
 // existing restore ownership checkpoints; before it, compare the raw witness.
 if(!cloudRestoring&&(localStorage.getItem(SU.RESET_KEY)!==context.reset||!flushed&&CS.KEYS.some(key=>localStorage.getItem(key)!==context.raw[key])))throw new Error('Saved progress changed since this preview. Open Import Progress again.');
 if(animating||customImageBusy||slotBusy||passivePolling||movingPanels?.status().editing||surveyViewActive()||surveys?.status().pending||surveys?.status().screenPhase||dailyTasks?.status().pending||dailyStreak?.status().pending||interest?.status().pending||cloudPending||cloudClient?.status().pending||cloudClient?.status().recovery?.active)throw new Error('Finish the current save, survey, image or cloud action, then open Import Progress again.');
}
