function abandonCurrentRun(){const context=pendingAbandonRun;let completed=false;const saved=act(()=>{assertAbandonReady();if(!context||context.run!==run||context.market!==JSON.stringify(profile.stockMarket?.active||null))throw new Error('The run or prediction changed. Reopen Abandon run to confirm the current state.');const next=JSON.parse(JSON.stringify(run));E.abandon(next);forfeitMarketForReplacement('Confirmed abandonment of origin run: stake and possible return forfeited.');market?.reset();run=next;selected=[];page='home';closeModal();completed=true},'',{action:'abandon'});if(completed)toast(saved?'Run abandoned. Earned XP and unlocks are saved.':'Run ended in this tab, but saving failed. Reload may restore the earlier run.')}
function confirmNew(){pendingRunReplacement=null;if(pendingMarket()||run&&!['won','lost'].includes(run.phase)){modal('Start over?',`<p>Your current run will be replaced. Lifetime statistics stay saved.</p>${marketForfeitWarning()}<div class="sheet-actions">${btn(pendingMarket()?'Forfeit prediction & start new run':'Start new run','confirm-new','danger')}${btn('Keep my run','close-modal','ghost')}</div>`)}else startNew()}
function startNew(confirmed=false){if(pendingMarket()&&confirmed!==true){confirmNew();return}act(()=>{if(!deckUnlocked(deckId))throw new Error('Win the previous deck to unlock this one.');const next=E.newRun(deckId,prefs.seed||undefined,{stake:chosenStake().id,playerLevel:playerLevel(),coinUnlocks:coinUnlockIds(),handSortMode:prefs.handSortMode,level10Deal:playerLevel()>=10&&prefs.level10Deal===true});if(PT&&playerLevel()>=12)E.setPotionState?.(next,profile.potions,Date.now());forfeitMarketForReplacement();market?.reset();run=next;run._uiSeeded=!!prefs.seed;run._uiId=newRunId();ER.seedRun(profile,run);if(SM)run._stockMarket=profile.stockMarket;profile.runs++;selected=[];page='game';closeModal();window.scrollTo(0,0)});batteryUsage()}
function setAppRun(s,confirmed=false){if(!validRun(s))throw new Error('Invalid run.');assertEconomyWritable();if(pendingMarket()&&s!==run&&confirmed!==true){pendingRunReplacement=s;modal('Replace origin run?',`<p>This replacement changes your current run.</p>${marketForfeitWarning()}<div class="sheet-actions">${btn('Forfeit prediction & replace run','confirm-set-run','danger')}${btn('Keep my run','close-modal','ghost')}</div>`);return false}batteryController?.suspend();batteryController?.tick();if(s!==run){forfeitMarketForReplacement();market?.reset()}passiveHeartbeat();capturePassiveJoker();cancelMotion();run=s;capturePassiveJoker();if(!run._uiId)run._uiId=newRunId();if(SM)run._stockMarket=profile.stockMarket;dailyTasks?.recover(run);pullPotionState();syncPotionClock();pendingRunReplacement=null;page='game';selected=[];persist();batteryUsage();void dailyTasks?.retry();render();return true}
